         WHERE c.table_schema = 'public' AND c.table_name = t.table_name) AS columns
  FROM information_schema.tables t
 WHERE table_schema = 'public' AND table_name IN ('partner_passenger_transport_profiles', 'partner_passenger_transport_items', 'partner_photography_profiles', 'partner_photography_items', 'partner_power_cooling_profiles', 'partner_power_cooling_items', 'partner_priest_rituals_profiles', 'partner_priest_rituals_items', 'partner_safety_facilities_profiles', 'partner_security_services_profiles')
 ORDER BY table_name;
